  assert.equal(job.origin, "chain");
  assert.deepEqual(job.criteria.map((c) => c.id), ["C1", "C2"]);
  const phases = seen.map((p) => p.phase);
  assert.equal(phases[0], "awaiting_wallet");
  assert.ok(phases.includes("submitted") && phases.includes("in_consensus"));
