test("only the worker can deliver, with a link the contract accepts", async () => {
  const { sim, as } = await accepted();
  const n = sim.sendCount;
  assert.equal((await failureOf(as(ALICE).submitDelivery("job-1", "https://example.org/w"))).kind, "precondition");
  assert.equal((await failureOf(as(CAROL).submitDelivery("job-1", "https://example.org/w"))).kind, "precondition");
  for (const bad of ["http://example.org", "https://localhost/x", "https://example.org/x#top", "https://example.org:8443/x", ""]) {
    const e = await failureOf(as(BOB).submitDelivery("job-1", bad));
    assert.equal(e.kind, "validation", bad);
    assert.equal(e.field, "url");
  }
  assert.equal(sim.sendCount, n, "nothing was sent");
  const { agreement, receipt } = await as(BOB).submitDelivery("job-1", "  https://example.org/work  ");
  assert.equal(agreement.deliveryCount, 1);
  assert.equal(receipt.id, "rcpt-1");
  assert.equal(receipt.deliveryIndex, 1);
  assert.equal(receipt.url, "https://example.org/work");
  assert.equal(receipt.status, "PENDING");
  assert.equal(receipt.evidenceHash, null);
});

test("a pending delivery can be replaced once; the old receipt is kept as superseded", async () => {
  const { as } = await accepted();
  await as(BOB).submitDelivery("job-1", "https://example.org/dead");
  const second = await as(BOB).submitDelivery("job-1", "https://example.org/fixed");
  assert.equal(second.receipt.deliveryIndex, 2);
  const receipts = await as(BOB).getReceipts(second.agreement);
  assert.deepEqual(receipts.map((r) => r.status), ["SUPERSEDED", "PENDING"]);
  const third = await failureOf(as(BOB).submitDelivery("job-1", "https://example.org/third"));
  assert.match(third.message, /No deliveries are left/);
});

test("two deliveries in total, including a correction after 'needs revision'", async () => {
  const { as } = await accepted();
  const d1 = await as(BOB).submitDelivery("job-1", "https://example.org/needs-revision");
  const v1 = await as(ALICE).requestVerification("job-1", d1.receipt.id);
  assert.equal(v1.agreement.status, "NEEDS_REVISION");
  const d2 = await as(BOB).submitDelivery("job-1", "https://example.org/better");
  assert.equal(d2.agreement.status, "IN_PROGRESS");
  const v2 = await as(ALICE).requestVerification("job-1", d2.receipt.id);
  assert.equal(v2.agreement.status, "VERIFIED");
  assert.equal((await failureOf(as(BOB).submitDelivery("job-1", "https://example.org/again"))).kind, "precondition");
});

