test("verification: the receipt comes from the contract and matches the agreement", async () => {
  const { as } = await accepted();
  const d = await as(BOB).submitDelivery("job-1", "https://example.org/ok");
  const seen: string[] = [];
  const { agreement, receipt } = await as(ALICE).requestVerification("job-1", d.receipt.id, { onProgress: (p) => seen.push(p.phase) });
  assert.equal(agreement.status, "VERIFIED");
  assert.equal(receipt.status, "EVALUATED");
  assert.equal(receipt.overallStatus, "VERIFIED");
  assert.equal(receipt.evaluationRequestedBy, ALICE);
  assert.equal(receipt.evidenceHash, "e".repeat(64));
  assert.equal(receipt.evidenceSize, 1234);
  assert.deepEqual(receipt.results.map((r) => r.criterionId), ["C1", "C2"]);
  assert.ok(receipt.results.every((r) => r.status === "MET" && r.evidenceExcerpt.length > 0));
  assert.equal(receipt.illustrative, false);
  assert.equal(seen[seen.length - 1], "decided");
});

test("inconclusive and needs-revision outcomes come through unchanged", async () => {
  const a = await accepted();
  const d = await a.as(BOB).submitDelivery("job-1", "https://example.org/inconclusive");
  const r = await a.as(BOB).requestVerification("job-1", d.receipt.id);
  assert.equal(r.agreement.status, "INCONCLUSIVE");
  assert.equal(r.receipt.results[1]!.status, "UNVERIFIABLE");
  assert.equal(r.receipt.results[1]!.evidenceExcerpt, "");
});

