test("when the validators cannot open the link the delivery stays pending", async () => {
  const { as } = await accepted();
  const d = await as(BOB).submitDelivery("job-1", "https://example.org/unreachable");
  const e = await failureOf(as(ALICE).requestVerification("job-1", d.receipt.id));
  assert.equal(e.kind, "tx_failed");
  assert.equal(e.message, "The validators could not open the delivered link.");
  assert.equal(e.retryable, true);
  const job = (await as(ALICE).getAgreement("job-1"))!;
  assert.equal(job.status, "IN_PROGRESS");
  const receipts = await as(ALICE).getReceipts(job);
  assert.equal(receipts[0]!.status, "PENDING");
});

