test("validators that never decide: timeout, the hash is kept, nothing is resubmitted", async () => {
  let clock = 0;
  const { sim, as, pending } = setup(ALICE, { now: () => (clock += 60_000), maxWaitMs: 5 * 60_000 });
  void as;
  sim.nextWriteSteps = ["PENDING", "PROPOSING"];
  const repo = new ChainRepository({ gateway: sim, actor: ALICE, pending, sleep: async () => {}, pollIntervalMs: 0, now: () => (clock += 60_000), maxWaitMs: 5 * 60_000 });
  const e = await failureOf(repo.createAgreement(terms));
  assert.equal(e.kind, "timeout");
  assert.ok(e.txHash);
  assert.equal(sim.sendCount, 1);
  const left = pending.forAccount(ALICE, sim.contractAddress);
  assert.equal(left.length, 1);
  assert.equal(left[0]!.hash, e.txHash);
  const state = await repo.checkPending(e.txHash!);
  assert.equal(state.phase, "in_consensus");
});

