test("pending transactions are scoped to the account and contract", () => {
  const store = new PendingStore(memoryStorage());
  const hash = "0x" + "9".repeat(64);
  store.add({ hash, method: "create_job", label: "x", actor: ALICE, contract: "0xAbC0000000000000000000000000000000000001", submittedAt: 1 });
  assert.equal(store.forAccount(ALICE, "0xabc0000000000000000000000000000000000001").length, 1);
  assert.equal(store.forAccount(BOB, "0xabc0000000000000000000000000000000000001").length, 0);
  assert.equal(store.forAccount(ALICE, "0xabc0000000000000000000000000000000000002").length, 0);
  assert.equal(store.forAccount(null, "0xabc0000000000000000000000000000000000001").length, 0);
  store.remove(hash);
  assert.equal(store.forAccount(ALICE, "0xabc0000000000000000000000000000000000001").length, 0);
});

