test("getLimits refuses malformed limits", async () => {
  const { sim, repo } = setup();
  sim.limitsOverride = { max_criteria: 0 };
  const e = await repo.getLimits().then(() => null, (x) => x);
  assert.ok(e instanceof ReadError && e.kind === "bad_data");
  sim.limitsOverride = { min_criteria: 30 };
  const e2 = await repo.getLimits().then(() => null, (x) => x);
  assert.ok(e2 instanceof ReadError && e2.kind === "bad_data", "min above max is refused");
  sim.limitsOverride = { min_excerpt_len: 999 };
  assert.ok((await repo.getLimits().then(() => null, (x) => x)) instanceof ReadError);
});
